{
  "assignment_title": "Algebra II — Homework 7",
  "sections": [
    {
      "section_id": "A",
      "title": "Section A — Linear equations",
      "max_score": 10,
      "criteria": "Sum rubric components exactly; allowed scores per question are listed in marking_criteria",
      "questions": [
        {
          "question_id": "Q1",
          "prompt": "Solve for x: 3x + 7 = 22",
          "max_score": 5,
          "marking_criteria": "Award exactly one total (max 5) by summing only these components: 2 pts for subtracting 7 to get 3x=15; 2 pts for dividing to x=5; 1 pt for stating final answer x=5. If only the final answer x=5 is shown with no intermediate steps, award exactly 3 pts (not 5). Wrong answer or blank: 0."
        },
        {
          "question_id": "Q2",
          "prompt": "Solve for y: 2(y - 4) = 10",
          "max_score": 5,
          "marking_criteria": "Apply exactly one band — never sum components when an alternate band applies. Band B first: if student shows 2y−8=10 and 2y=18 but final y ≠ 9, award exactly 2 pts. Band C next: if only final answer y=9 appears with no intermediate steps (no distributing, no 2y=18), award exactly 3 pts — a correct answer alone is not full marks. Band A: if full method with y=9, sum components for exactly 5 pts (1 pt distributing to 2y−8=10; 1 pt adding 8 to 2y=18; 1 pt dividing by 2; 2 pts final y=9). Otherwise: 0."
        }
      ]
    },
    {
      "section_id": "B",
      "title": "Section B — Quadratic factoring",
      "max_score": 15,
      "criteria": "Use only the discrete scores listed in marking_criteria — no partial credit beyond those bands",
      "questions": [
        {
          "question_id": "Q3",
          "prompt": "Factor: x² + 5x + 6",
          "max_score": 5,
          "marking_criteria": "Exactly 5 pts for correct factorisation (x+2)(x+3) or equivalent order; exactly 0 otherwise. No other scores."
        },
        {
          "question_id": "Q4",
          "prompt": "Solve: x² - 9 = 0",
          "max_score": 10,
          "marking_criteria": "Award exactly one of: 10 pts if both roots x=3 AND x=−3 are stated (±3 counts as both); 5 pts if only one root is given OR factorisation is shown without both roots stated; 0 if wrong roots or no valid work."
        }
      ]
    },
    {
      "section_id": "C",
      "title": "Section C — Word problems",
      "max_score": 15,
      "criteria": "Sum rubric components exactly; diagram alone is never full marks without equation attempt",
      "questions": [
        {
          "question_id": "Q5",
          "prompt": "A train leaves at 2pm at 60 mph. Another leaves at 3pm at 90 mph on the same line. When do they meet if 210 miles apart?",
          "max_score": 15,
          "marking_criteria": "If correct meeting time 4pm AND a valid distance-rate equation (e.g. 60(t+1)+90t=210): award exactly 15 pts (diagram not required). Otherwise sum only: 5 pts if diagram/sketch shown or explicitly described; 5 pts if a valid distance-rate equation is set up; 3 pts (not 5) if an equation is attempted but uses the wrong distance model (e.g. 60d+90d=210); 5 pts if meeting time is 4pm. Wrong meeting time caps total at 10 even with diagram and equation attempt. Final answer with no equation and no diagram: exactly 0."
        }
      ]
    }
  ]
}

