(doc) => {
  const lines = doc.content.split('\n').filter(l => l.trim());
  const questions = lines.map(l => l.split('(')[0].trim());
  const maxScores = lines.map(l => parseInt(l.match(/\(max (\d+)/)?.[1] || '0'));
  return { questions, max_scores: maxScores };
}

(docs) => docs.map(doc => {
  const content = doc.content;
  const nameMatch = content.match(/Student:\s*(.+)/);
  return {
    student_name: nameMatch?.[1]?.trim() || 'Unknown',
    content: content
  };
})

